mapper.select:
SELECT
count(*)
FROM
BASIL_SEC_PRD.PREP_MASTER_ORDER pmo
JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID)
JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstat ON pmo.ORDER_STATUS = scavstat.SCV_OID
LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID)
LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstatus ON pmo.ORDER_STATUS = scavstatus.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID
LEFT JOIN (
select response.* from ( select response.*,row_number() over (partition by mo_oid order by response_date desc)
rn from BASIL_SEC_PRD.XREF_RESPONSE as response ) AS response where response.rn=1 ) AS res on
res.MO_OID=pmo.MO_OID


        AND mc.MC_OID = #{id}


        AND

            #{item}



        AND scavdept.SCV_OID = #{department}


        AND scavtype.SCV_OID = #{type}


        AND scavstatus.SCV_OID = #{status}




        AND resp.RESPONSE_DATE = #{lastResponse}



        AND mc.CUSTOMER_ORGANIZATION = #{customerOrganization}



        AND mc.MC_OID = #{customerId}



        AND
        pmo.MO_OID IN (
        SELECT pxm.MO_OID
        FROM BASIL_SEC_PRD.PREP_XREF_MATERIALS AS pxm
        WHERE pxm.MSN_OID IN (
        SELECT msn.MSN_OID
        FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER AS msn
        WHERE msn.SERIAL_NUMBER IN

            #{item}

        )
        )


        AND user.NAME = #{responder} OR user.NAME IS NULL


        AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}

SELECT
pmo.MO_OID as ticketId,
scavstatus.VALUE as status,
scavdept.VALUE as department,
scavtype.VALUE as type,
mc.CUSTOMER_ORGANIZATION as customerOrganization,
pmo.ORDER_DATE as createdDate,
resp.RESPONSE_DATE as lastResponse,
user.NAME as responder

FROM
BASIL_SEC_PRD.PREP_MASTER_ORDER pmo
JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID)
JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstat ON pmo.ORDER_STATUS = scavstat.SCV_OID
LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID)
LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID

LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstatus ON pmo.ORDER_STATUS = scavstatus.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID
LEFT JOIN (
select response.* from ( select response.*,row_number() over (partition by mo_oid order by response_date desc)
rn from BASIL_SEC_PRD.XREF_RESPONSE as response ) AS response where response.rn=1 ) AS res on
res.MO_OID=pmo.MO_OID


        AND mc.MC_OID = #{id}


        AND

            #{item}



        AND scavdept.SCV_OID = #{department}


        AND scavtype.SCV_OID = #{type}


        AND scavstatus.SCV_OID = #{status}



        AND mc.CUSTOMER_ORGANIZATION = #{customerOrganization}



        AND resp.RESPONSE_DATE = #{lastResponse}



        AND mc.MC_OID = #{customerId}



        AND
        pmo.MO_OID IN (
        SELECT pxm.MO_OID
        FROM BASIL_SEC_PRD.PREP_XREF_MATERIALS AS pxm
        WHERE pxm.MSN_OID IN (
        SELECT msn.MSN_OID
        FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER AS msn
        WHERE msn.SERIAL_NUMBER IN

            #{item}

        )
        )



        AND LOWER(user.NAME) LIKE CONCAT ('%', LOWER(#{responder}), '%')


        AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}



    ORDER BY ${sortColumns}

LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT SERIAL_NUMBER as serialNumber, msnOID, xmOID, pxmOID, warrantyExpDate, warrantyStatus, model, version, cosmeticPrice, diagnosticPrice, minorPrice, existInAnotherTicket, moOID, cosmetic, keyInjection FROM ( SELECT msn.SERIAL_NUMBER, msn.MSN_OID as msnOID, xm.XM_OID as xmOID, pxm.XM_OID as pxmOID, COALESCE(msn.WARRANTY_VOIDED_DATE, msn.WARRANTY_END_DATE) AS warrantyExpDate, CASE WHEN msn.WARRANTY_END_DATE IS NULL AND msn.WARRANTY_VOIDED_DATE IS NULL THEN 'N/A' WHEN CURRENT_DATE < COALESCE(msn.WARRANTY_VOIDED_DATE, msn.WARRANTY_END_DATE) THEN 'Under Warranty' ELSE 'Out Of Warranty' END AS warrantyStatus, mp.PART_NUMBER_LONG AS model, mp.VERSION_NUMBER AS version, COALESCE(rc1.COSMETIC, rc2.COSMETIC) AS cosmeticPrice, COALESCE(rc1.DIAGNOSTIC, rc2.DIAGNOSTIC) AS diagnosticPrice, COALESCE(rc1.MINOR, rc2.MINOR) AS minorPrice, COALESCE(rc1.KEY_INJECTION, rc2.KEY_INJECTION) AS keyInjection, IF((xm.XM_OID IS NULL OR xm.STATUS = 113) AND (pxm.XM_OID is null), FALSE, TRUE) AS existInAnotherTicket, ROW_NUMBER() OVER (PARTITION BY msn.SERIAL_NUMBER ORDER BY IF(xm.XM_OID IS NULL OR xm.STATUS = 113, FALSE, TRUE) DESC) AS RN, IF(xm.XM_OID is not null, xm.MO_OID, pxm.MO_OID) as moOID, COALESCE(xm.COSMETIC, pxm.COSMETIC) AS cosmetic
FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn LEFT JOIN BASIL_ODS_PRD.MASTER_PART mp ON msn.PART_OID = mp.PART_OID LEFT JOIN BASIL_ODS_PRD.XREF_MATERIALS xm ON msn.MSN_OID = xm.MSN_OID LEFT JOIN BASIL_SEC_PRD.PREP_XREF_MATERIALS pxm ON msn.MSN_OID = pxm.MSN_OID LEFT JOIN BASIL_SEC_PRD.REPAIR_COST rc1 ON mp.PART_NUMBER_SHORT = rc1.PART_NUMBER_SHORT AND rc1.customer = #{companyId} LEFT JOIN BASIL_SEC_PRD.REPAIR_COST rc2 ON mp.PART_NUMBER_SHORT = rc2.PART_NUMBER_SHORT AND rc2.customer IS NULL AND rc1.RC_OID IS NULL WHERE msn.SERIAL_NUMBER IN
#{item, jdbcType=INTEGER}
) AS CTE
(existInAnotherTicket = 1) OR (existInAnotherTicket = 0 AND RN = 1)

